];

function _tryCall(fnName, message) {
    try {
        var fn = typeof globalThis !== 'undefined' ? globalThis[fnName] : undefined;
        if (!fn && typeof window !== 'undefined') fn = window[fnName];
        if (typeof fn === 'function') {
