var aiChatModule = loadModule('js/common/aiChat.js');

var PROVIDER_NAMES = [
    'gemini_ai_chat',
    'openai_ai_chat',
    'anthropic_ai_chat',
    'ollama_ai_chat',
    'dial_ai_chat',
    'bedrock_ai_chat'
];

function clearProviders() {
    PROVIDER_NAMES.forEach(function(name) {
        try { delete globalThis[name]; } catch (e) { globalThis[name] = undefined; }
    });
}

function setProvider(name, fn) {
    globalThis[name] = fn;
}

