        } finally {
            console.warn = origWarn;
        }
        clearProviders();
    });

    test('falls through when a provider resolves undefined', function() {
        clearProviders();
        var calls = [];
        setProvider('gemini_ai_chat', function(message) { calls.push('gemini_ai_chat'); return undefined; });
